import os
import xarray as xr
import json

print("=== FINAL VERIFICATION ===")

# Check mhw_mask.nc
if os.path.exists('output/mhw_mask.nc'):
    try:
        ds = xr.open_dataset('output/mhw_mask.nc')
        print("✓ mhw_mask.nc exists and is readable")
        print(f"  Dimensions: {ds.dims}")
        print(f"  Variables: {list(ds.data_vars.keys())}")
        ds.close()
    except Exception as e:
        print(f"✗ Error reading mhw_mask.nc: {e}")
else:
    print("✗ mhw_mask.nc not found")

# Check report.json
if os.path.exists('output/report.json'):
    try:
        with open('output/report.json', 'r') as f:
            report = json.load(f)
        print("✓ report.json exists and is readable")
        required_fields = ['region', 'baseline_analysed', 'target_analysed', 'events', 'complete', 'caveats']
        for field in required_fields:
            if field in report:
                print(f"  ✓ {field}: present")
            else:
                print(f"  ✗ {field}: missing")
    except Exception as e:
        print(f"✗ Error reading report.json: {e}")
else:
    print("✗ report.json not found")

print("\n=== TASK COMPLETED SUCCESSFULLY ===")"}

